class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        ans = 0
        for a, b in zip(s, t):
            x, y = ord(a) - 97, ord(b) - 97
            if x == y:
                continue
            cw = cc = 0
            i = x
            while i != y:
                cw += nextCost[i]
                i = (i + 1) % 26
            j = x
            while j != y:
                j = (j - 1) % 26
                cc += previousCost[j]
            ans += min(cw, cc)
        return ans

