class Solution {
public:
    long long shiftDistance(string s, string t, vector<int>& nextCost, vector<int>& previousCost) {
        long long ans = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            int x = s[i] - 'a', y = t[i] - 'a';
            if (x == y) continue;
            long long cw = 0, cc = 0;
            for (int j = x; j != y; j = (j + 1) % 26) cw += nextCost[j];
            for (int j = x; j != y; ) { j = (j + 25) % 26; cc += previousCost[j]; }
            ans += min(cw, cc);
        }
        return ans;
    }
};

